"""Tests for .github/hooks/guard.py: the shared rules, then this repository's own (local.py). Same file in both repositories.

    python -m unittest discover -s .github/hooks -p 'test_*.py'
"""
import importlib.util
import io
import json
import pathlib
import subprocess
import sys
import unittest

HERE = pathlib.Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location("guard", HERE / "guard.py")
G = importlib.util.module_from_spec(spec)
spec.loader.exec_module(G)
REPO = G.ROOT.name


def hook(event, data):
    r = subprocess.run([sys.executable, str(HERE / "guard.py"), event], input=json.dumps(data), capture_output=True, text=True)
    return r.returncode, (json.loads(r.stdout) if r.stdout.strip().startswith("{") else r.stdout), r.stderr


def decision(event, data):
    code, o, _ = hook(event, data)
    return o.get("hookSpecificOutput", {}).get("permissionDecision") if isinstance(o, dict) else None


class Shell(unittest.TestCase):
    def refused(self, cmd):
        return G.bash_problem(cmd, str(G.ROOT)) is not None

    def test_push(self):
        for cmd in ("git push --force origin x", "git push -f origin x", "git push origin +x", "git push -uf origin x",
                    "git push origin main", "git push origin HEAD:main", "cd a && git push origin main"):
            self.assertTrue(self.refused(cmd), cmd)
        for cmd in ("git push -u origin claude/project-thread-x", "git push --force-with-lease origin claude/x",
                    "git push -u origin feature-fix", "git push origin claude/main-menu"):
            self.assertFalse(self.refused(cmd), cmd)

    def test_commit_trailers(self):
        self.assertTrue(self.refused('git commit -m "Fix\n\nCo-Authored-By: Claude <noreply@anthropic.com>"'))
        self.assertTrue(self.refused("git commit -F - <<'EOF'\nFix\n\nClaude-Session: https://x\nEOF"))
        self.assertFalse(self.refused('git commit -m "Fix the header"'))

    def test_release_and_rm(self):
        self.assertTrue(self.refused("gh workflow run release.yml -f tag=v1"))
        self.assertTrue(self.refused("rm -rf .git"))
        self.assertTrue(self.refused("rm -rf ~"))
        self.assertFalse(self.refused("rm -rf build/frames"))

    def test_trim_wraps_only_noisy_commands(self):
        noisy = getattr(G.L, "TRIM", [])
        if noisy:
            self.assertIsNone(G.trim_command({"command": "ls -la"}))
            self.assertIsNone(G.trim_command({"command": "x | tail", "run_in_background": False}))

    def test_trim_keeps_failures_and_end(self):
        text = "\n".join([f"ok {i}" for i in range(200)] + ["FAIL: test_x", "boom"] + [f"ok {i}" for i in range(200, 300)])
        buf = io.StringIO()
        old = sys.stdout
        sys.stdout = buf
        try:
            G.trim(io.StringIO(text))
        finally:
            sys.stdout = old
        out = buf.getvalue()
        self.assertIn("FAIL: test_x", out)
        self.assertIn("ok 299", out)
        self.assertNotIn("ok 50\n", out)
        self.assertLess(len(out.splitlines()), 60)


class Merges(unittest.TestCase):
    def test_squash_with_explicit_message(self):
        self.assertIsNotNone(G.merge_problem({"merge_method": "merge", "commit_title": "t", "commit_message": "m"}))
        self.assertIsNotNone(G.merge_problem({"merge_method": "squash"}))
        self.assertIsNotNone(G.merge_problem({"merge_method": "squash", "commit_title": "T (#1)",
                                              "commit_message": "m\n\nCo-authored-by: Claude <noreply@anthropic.com>"}))
        self.assertIsNone(G.merge_problem({"merge_method": "squash", "commit_title": "T (#1)", "commit_message": "What and why."}))

    def test_release_workflow_run_is_refused(self):
        self.assertEqual(decision("pre-merge", {"tool_name": "mcp__github__actions_run_trigger",
                                                "tool_input": {"repo": REPO, "method": "run_workflow", "workflow_id": "release.yml"}}), "deny")

    def test_another_repository_is_left_alone(self):
        self.assertIsNone(decision("pre-merge", {"tool_name": "mcp__github__merge_pull_request",
                                                 "tool_input": {"repo": "someone-else", "merge_method": "merge"}}))


class Edits(unittest.TestCase):
    def test_secrets(self):
        self.assertEqual(G.edit_problem("a.py", "token = 'dapi" + "0" * 32 + "'", "")[0], "deny")
        self.assertEqual(G.edit_problem(".env", "X=1", "")[0], "deny")
        self.assertEqual(G.edit_problem(".claude/settings.local.json", "{}", "")[0], "deny")
        self.assertIsNone(G.edit_problem("docs/a.md", "the token comes from DATABRICKS_TOKEN", ""))

    def test_generated(self):
        self.assertEqual(G.edit_problem("x.yaml", "a: 1", "# Generated by scripts/gen.py. Don't edit it: run the script\n")[0], "deny")

    def test_hook_outputs(self):
        self.assertEqual(decision("pre-edit", {"tool_input": {"file_path": str(G.ROOT / ".env"), "content": "X=1"}}), "deny")
        self.assertIsNone(decision("pre-edit", {"tool_input": {"file_path": "/elsewhere/.env", "content": "X=1"}}))
        self.assertEqual(decision("pre-bash", {"tool_input": {"command": "git push origin main"}, "cwd": str(G.ROOT)}), "deny")


class Reads(unittest.TestCase):
    def test_big_file(self):
        big = pathlib.Path(G.LOG_DIR) / "big-test.txt"
        big.parent.mkdir(parents=True, exist_ok=True)
        big.write_text("x" * (G.BIG_BYTES + 10))
        try:
            self.assertEqual(decision("pre-read", {"tool_input": {"file_path": str(big)}}), "deny")
            self.assertIsNone(decision("pre-read", {"tool_input": {"file_path": str(big), "limit": 100}}))
        finally:
            big.unlink()


class Parent(unittest.TestCase):
    """a session that starts in the folder holding both repositories: install writes its settings, dispatch runs every guard"""

    def test_install_points_every_hook_at_dispatch(self):
        import tempfile
        with tempfile.TemporaryDirectory() as d:
            subprocess.run([sys.executable, str(HERE / "guard.py"), "install", d], check=True, capture_output=True)
            settings = json.loads((pathlib.Path(d) / ".claude" / "settings.json").read_text())
            commands = [h["command"] for groups in settings["hooks"].values() for g in groups for h in g["hooks"]]
            self.assertTrue(commands)
            self.assertTrue(all(" dispatch " in c and c.startswith('python "/') for c in commands), commands)

    def test_dispatch_joins_the_guards(self):
        r = subprocess.run([sys.executable, str(HERE / "guard.py"), "dispatch", "pre-bash"],
                           input=json.dumps({"tool_input": {"command": "git push --force origin x"}, "cwd": str(G.ROOT.parent)}),
                           capture_output=True, text=True)
        self.assertEqual(json.loads(r.stdout)["hookSpecificOutput"]["permissionDecision"], "deny")
        r = subprocess.run([sys.executable, str(HERE / "guard.py"), "dispatch", "pre-bash"],
                           input=json.dumps({"tool_input": {"command": "ls"}, "cwd": str(G.ROOT.parent)}), capture_output=True, text=True)
        self.assertEqual((r.returncode, r.stdout.strip()), (0, ""))


class Local(unittest.TestCase):
    """this repository's own rules"""

    @unittest.skipUnless(REPO == "learning-data", "learning-data's rules")
    def test_learning_data(self):
        L = G.L
        self.assertTrue(G.bash_problem("python films/x/1-y/source/tools/render.py", None))
        self.assertTrue(G.bash_problem("python .github/scripts/affected.py --all --run", None))
        self.assertTrue(G.bash_problem("python site-tools/smoke.py", None))
        self.assertIsNone(G.bash_problem("python site-tools/smoke.py --pages '[\"\"]'", None))
        self.assertIsNone(G.bash_problem("python .github/scripts/affected.py --run", None))
        self.assertIsNotNone(G.trim_command({"command": "python .github/scripts/affected.py --run"}))
        old = json.dumps({"kicker": "A", "kicker_es": "B", "h1": "T", "h1_es": "T", "lead": "L", "lead_es": "L"})
        long = json.dumps({"kicker": "A", "kicker_es": "B", "h1": "T", "h1_es": "T", "lead": "L" * 301, "lead_es": "L"})
        probs = L.check_file("films/s/1-f/site.json", old, long)
        self.assertTrue(any(p.startswith("!lead is 301") for p in probs), probs)
        self.assertTrue(any("English only" in p for p in probs), probs)
        mod = json.dumps({"kicker": "A", "kicker_es": "B", "lead": "the module's films", "lead_es": "L"})
        self.assertTrue(any("topic" in p for p in L.check_file("films/s/1-f/site.json", old, mod)))
        self.assertTrue(L.check_file("films/s/1-f/source/src/narration.js", '"text": "Hello."',
                                     '"text": "Something had to change."'))
        self.assertTrue(L.check_file("films/s/1-f/source/src/narration.js", '"text": "Hello."', '"text": "It is in public preview."'))
        self.assertEqual(L.check_file("films/s/1-f/source/src/narration.js", '"text": "Hello."', '"text": "Hello there."'), [])
        self.assertTrue(L.stop_checks(["films/s/1-f/source/src/narration.js"]))
        self.assertEqual(G.edit_problem(".github/workflows/release.yml", "x", "")[0], "ask")
        self.assertEqual(decision("pre-read", {"tool_input": {"file_path": str(G.ROOT / "site/assets/x/film.js")}}), "deny")

    @unittest.skipUnless(REPO == "learning-data-project", "learning-data-project's rules")
    def test_learning_data_project(self):
        L = G.L
        refused = lambda c: G.bash_problem(c, None) is not None
        self.assertTrue(refused("dbt build --target databricks --profiles-dir ."))
        self.assertTrue(refused("cd 30-data-project && dbt run -t agent"))
        self.assertTrue(refused("dbt build --target prod"))
        self.assertTrue(refused("dbt show --select x --limit 500"))
        self.assertTrue(refused("databricks bundle deploy -t prod"))
        self.assertFalse(refused("dbt build --profiles-dir ."))
        self.assertFalse(refused("dbt build --target duckdb --profiles-dir ."))
        self.assertFalse(refused("dbt parse --target databricks --profiles-dir . --no-partial-parse"))
        self.assertFalse(refused("dbt show --select x --limit 20"))
        weak = L.check_file("30-data-project/models/core/student/_student__models.yml",
                            "tests:\n  - unique\n", "tests:\n  - unique:\n      config:\n        severity: warn\n")
        self.assertTrue(weak and weak[0].startswith("tests weakened") or any("weaken" in p for p in weak), weak)
        self.assertTrue(L.check_file("30-data-project/profiles.yml", "", "    token: abc123secretvalue\n"))
        self.assertEqual(L.check_file("30-data-project/profiles.yml", "", "    token: \"{{ env_var('DATABRICKS_TOKEN') }}\"\n"), [])


if __name__ == "__main__":
    unittest.main()
